param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'midpoint-rounding-type-identity-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Value($p){switch($p.kind){'null'{return $null};'object'{return [object]::new()};'string'{return [string]$p.value};'enum'{return [Enum]::ToObject([type]::GetType($p.enumType,$true),[int]$p.value)};'int32'{return [int]::Parse($p.value)};'int32Facade'{return [int]::Parse($p.value)};'int16'{return [int16]::Parse($p.value)};'int64'{return [int64]::Parse($p.value)};'sbyte'{return [sbyte]::Parse($p.value)};'sbytePrimitive'{return [sbyte]::Parse($p.value)};'byte'{return [byte]::Parse($p.value)};'uint16'{return [uint16]::Parse($p.value)};'uint32'{return [uint32]::Parse($p.value)};'uint64'{return [uint64]::Parse($p.value)};'bool'{return $p.value -eq '1'};'char'{return [char][int]$p.value};'single'{return [single]::Parse($p.value,[Globalization.CultureInfo]::InvariantCulture)};'double'{return [double]::Parse($p.value,[Globalization.CultureInfo]::InvariantCulture)};'decimal'{return [decimal]::Parse($p.value,[Globalization.CultureInfo]::InvariantCulture)};default{throw 'Unknown value profile'}}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=[Collections.Generic.List[object]]::new();$inventories=[Collections.Generic.List[object]]::new()
foreach($typeName in $plan.types){$type=[type]::GetType($typeName,$true);$names=[Enum]::GetNames($type);$values=[int[]][Enum]::GetValues($type);$inventories.Add([ordered]@{type=$typeName;names=$names;values=$values});$profiles=[Collections.Generic.List[object]]::new();foreach($p in $plan.profiles){$profiles.Add($p)};foreach($text in $names){$profiles.Add([pscustomobject]@{kind='string';value=$text})};foreach($method in $plan.methods){$member=$type.GetType().GetMethod($method,[type[]]@([object]));foreach($p in $profiles){$arguments=[object[]]::new(1);$arguments[0]=Value $p;try{$actual=$member.Invoke($type,$arguments);$result=[ordered]@{ok=$true;value=$actual}}catch{$result=Failure $_};$rows.Add([ordered]@{type=$typeName;method=$method;kind=$p.kind;value=$p.value;enumType=$(if($p.kind -eq 'enum'){$p.enumType}else{$null});result=$result})}}}
$lookups=[Collections.Generic.List[object]]::new();foreach($query in $plan.lookups){foreach($ignoreCase in @($false,$true)){$found=[type]::GetType($query,$false,$ignoreCase);$lookups.Add([ordered]@{query=$query;ignoreCase=$ignoreCase;result=$(if($null -eq $found){$null}else{$found.FullName})})}}
$midpoint=[MidpointRounding];$traits=[ordered]@{fullName=$midpoint.FullName;name=$midpoint.Name;namespace=$midpoint.Namespace;baseType=$midpoint.BaseType.FullName;underlyingType=[Enum]::GetUnderlyingType($midpoint).FullName;isEnum=$midpoint.IsEnum;isValueType=$midpoint.IsValueType;isPrimitive=$midpoint.IsPrimitive;isClass=$midpoint.IsClass;isInterface=$midpoint.IsInterface;isSealed=$midpoint.IsSealed;isAbstract=$midpoint.IsAbstract;isPublic=$midpoint.IsPublic;isVisible=$midpoint.IsVisible;hasElementType=$midpoint.HasElementType;containsGenericParameters=$midpoint.ContainsGenericParameters;defaultMembers=$midpoint.GetDefaultMembers().Count}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';inventories=$inventories.ToArray();rows=$rows.ToArray();traits=$traits;lookups=$lookups.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 22 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS MidpointRounding identity: $($rows.Count) enum queries, 17 traits and 22 lookups"
